export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[];
  draft?: boolean;
  layout?: string;
}

export interface Page {
  sourcePath: string;
  outputPath: string;
  frontmatter: Frontmatter;
  markdown: string;
  html: string;
  url: string;
}

export interface SiteConfig {
  source: string;
  templates: string;
  output: string;
  baseUrl: string;
  includeDrafts: boolean;
  siteTitle: string;
  siteDescription: string;
}

export interface BuildContext {
  config: SiteConfig;
  pages: Page[];
  tagMap: Map<string, Page[]>;
}

import { readFileSync } from "node:fs";
import matter from "gray-matter";
import type { Frontmatter, Page } from "./types.js";

export function parseFrontmatter(filePath: string, sourceDir: string): Page | null {
  const raw = readFileSync(filePath, "utf-8");
  const { data, content } = matter(raw);

  if (!data.title) return null;

  const frontmatter: Frontmatter = {
    title: String(data.title),
    date: data.date ? String(data.date) : undefined,
    tags: Array.isArray(data.tags)
      ? data.tags.map(String)
      : data.tags
        ? [String(data.tags)]
        : undefined,
    draft: data.draft === true || data.draft === "true",
    layout: data.layout ? String(data.layout) : undefined,
  };

  const rel = filePath.slice(sourceDir.length).replace(/^\//, "");
  const slug = rel.replace(/\.md$/, "").replace(/\\/g, "/");
  const outputPath = slug + "/index.html";

  return {
    sourcePath: filePath,
    outputPath,
    frontmatter,
    markdown: content,
    html: "",
    url: "/" + slug + "/",
  };
}

import { Marked } from "marked";
import { markedHighlight } from "marked-highlight";
import hljs from "highlight.js";

const marked = new Marked(
  markedHighlight({
    langPrefix: "hljs language-",
    highlight(code: string, lang: string) {
      if (lang && hljs.getLanguage(lang)) {
        return hljs.highlight(code, { language: lang }).value;
      }
      return hljs.highlightAuto(code).value;
    },
  }),
);

export function renderMarkdown(md: string): string {
  const html = marked.parse(md);
  if (typeof html === "string") return html;
  return "";
}

import { readFileSync, existsSync, readdirSync } from "node:fs";
import { join } from "node:path";
import Handlebars from "handlebars";

const compiledTemplates = new Map<string, HandlebarsTemplateDelegate>();
const compiledPartials = new Map<string, HandlebarsTemplateDelegate>();

function loadDirectory(dir: string, map: Map<string, HandlebarsTemplateDelegate>) {
  if (!existsSync(dir)) return;
  for (const file of readdirSync(dir)) {
    if (!file.endsWith(".hbs") && !file.endsWith(".handlebars")) continue;
    const name = file.replace(/\.(hbs|handlebars)$/, "");
    const content = readFileSync(join(dir, file), "utf-8");
    map.set(name, Handlebars.compile(content));
  }
}

export function initTemplates(templatesDir: string): void {
  compiledTemplates.clear();
  compiledPartials.clear();

  const partialsDir = join(templatesDir, "partials");
  loadDirectory(partialsDir, compiledPartials);

  Handlebars.registerHelper("formatDate", (date: string) => {
    if (!date) return "";
    return new Date(date).toLocaleDateString("en-US", {
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  });

  Handlebars.registerHelper("tagUrl", (tag: string) => `/tags/${encodeURIComponent(String(tag).toLowerCase().replace(/\s+/g, "-"))}/`);

  Handlebars.registerHelper("pageUrl", (url: string) => url);

  for (const [name, fn] of compiledPartials) {
    Handlebars.registerPartial(name, fn);
  }

  const templatesRoot = readdirSync(templatesDir).filter(
    (f) => (f.endsWith(".hbs") || f.endsWith(".handlebars")) && !f.startsWith("_"),
  );
  for (const file of templatesRoot) {
    const name = file.replace(/\.(hbs|handlebars)$/, "");
    compiledTemplates.set(name, Handlebars.compile(readFileSync(join(templatesDir, file), "utf-8")));
  }

  const layoutsDir = join(templatesDir, "layouts");
  if (existsSync(layoutsDir)) {
    for (const file of readdirSync(layoutsDir)) {
      if (!file.endsWith(".hbs") && !file.endsWith(".handlebars")) continue;
      const name = "layout:" + file.replace(/\.(hbs|handlebars)$/, "");
      compiledTemplates.set(name, Handlebars.compile(readFileSync(join(layoutsDir, file), "utf-8")));
    }
  }
}

export function renderTemplate(name: string, data: Record<string, unknown>): string {
  const tpl = compiledTemplates.get(name);
  if (!tpl) throw new Error(`Template "${name}" not found`);
  return tpl(data);
}

export function renderWithLayout(
  templateName: string,
  layoutName: string,
  data: Record<string, unknown>,
): string {
  const body = renderTemplate(templateName, data);
  const layoutKey = "layout:" + layoutName;
  const layoutTpl = compiledTemplates.get(layoutKey);
  if (!layoutTpl) throw new Error(`Layout "${layoutName}" not found`);
  return layoutTpl({ ...data, body });
}

export function templateExists(name: string): boolean {
  return compiledTemplates.has(name) || compiledTemplates.has("layout:" + name);
}

import type { Page, SiteConfig } from "./types.js";

function escapeXml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

export function generateRSS(pages: Page[], config: SiteConfig): string {
  const items = pages
    .filter((p) => p.frontmatter.date)
    .sort((a, b) => new Date(b.frontmatter.date!).getTime() - new Date(a.frontmatter.date!).getTime())
    .map((p) => {
      const url = config.baseUrl.replace(/\/$/, "") + p.url;
      const dateStr = new Date(p.frontmatter.date!).toUTCString();
      return `    <item>
      <title>${escapeXml(p.frontmatter.title)}</title>
      <link>${escapeXml(url)}</link>
      <guid isPermaLink="true">${escapeXml(url)}</guid>
      <pubDate>${dateStr}</pubDate>
      <description>${escapeXml(p.html.slice(0, 500))}</description>
    </item>`;
    })
    .join("\n");

  const lastBuild = new Date().toUTCString();
  const baseUrl = config.baseUrl.replace(/\/$/, "");

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(config.siteTitle)}</title>
    <link>${escapeXml(baseUrl)}</link>
    <description>${escapeXml(config.siteDescription)}</description>
    <lastBuildDate>${lastBuild}</lastBuildDate>
    <atom:link href="${escapeXml(baseUrl + "/rss.xml")}" rel="self" type="application/rss+xml"/>
${items}
  </channel>
</rss>`;
}

import { mkdirSync, writeFileSync, existsSync, readdirSync, statSync, copyFileSync } from "node:fs";
import { join, relative, dirname } from "node:path";
import { globSync } from "node:fs";
import type { Page, SiteConfig, BuildContext } from "./types.js";
import { parseFrontmatter } from "./frontmatter.js";
import { renderMarkdown } from "./markdown.js";
import { initTemplates, renderWithLayout, renderTemplate, templateExists } from "./templates.js";
import { generateRSS } from "./rss.js";

function walkDir(dir: string): string[] {
  const results: string[] = [];
  const entries = readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...walkDir(full));
    } else if (entry.name.endsWith(".md")) {
      results.push(full);
    }
  }
  return results;
}

export function build(config: SiteConfig): void {
  initTemplates(config.templates);

  const sourceFiles = walkDir(config.source);
  let pages: Page[] = [];

  for (const file of sourceFiles) {
    const page = parseFrontmatter(file, config.source);
    if (!page) continue;
    if (page.frontmatter.draft && !config.includeDrafts) continue;
    page.html = renderMarkdown(page.markdown);
    pages.push(page);
  }

  pages.sort((a, b) => {
    const da = a.frontmatter.date ? new Date(a.frontmatter.date).getTime() : 0;
    const db = b.frontmatter.date ? new Date(b.frontmatter.date).getTime() : 0;
    return db - da;
  });

  const tagMap = new Map<string, Page[]>();
  for (const page of pages) {
    for (const tag of page.frontmatter.tags || []) {
      const key = tag.toLowerCase().replace(/\s+/g, "-");
      if (!tagMap.has(key)) tagMap.set(key, []);
      tagMap.get(key)!.push(page);
    }
  }

  // Sort each tag's pages by date
  for (const [, tagPages] of tagMap) {
    tagPages.sort((a, b) => {
      const da = a.frontmatter.date ? new Date(a.frontmatter.date).getTime() : 0;
      const db = b.frontmatter.date ? new Date(b.frontmatter.date).getTime() : 0;
      return db - da;
    });
  }

  const ctx: BuildContext = { config, pages, tagMap };

  // Generate post pages
  const layout = "default";
  const postTemplate = templateExists("post") ? "post" : null;

  for (const page of pages) {
    const outputFile = join(config.output, page.outputPath);
    mkdirSync(dirname(outputFile), { recursive: true });
    const data = {
      ...page.frontmatter,
      content: page.html,
      url: page.url,
      page,
      pages,
      site: { title: config.siteTitle, description: config.siteDescription, baseUrl: config.baseUrl },
    };
    const rendered = postTemplate
      ? renderWithLayout(postTemplate, layout, data)
      : renderTemplate("layout:" + layout, { ...data, body: page.html });
    writeFileSync(outputFile, rendered);
  }

  // Generate index page
  if (templateExists("index")) {
    const indexFile = join(config.output, "index.html");
    mkdirSync(dirname(indexFile), { recursive: true });
    const data = {
      pages,
      site: { title: config.siteTitle, description: config.siteDescription, baseUrl: config.baseUrl },
    };
    writeFileSync(indexFile, renderWithLayout("index", layout, data));
  }

  // Generate tag pages
  if (templateExists("tag")) {
    for (const [tag, tagPages] of tagMap) {
      const tagFile = join(config.output, "tags", tag, "index.html");
      mkdirSync(dirname(tagFile), { recursive: true });
      const data = {
        tag,
        pages: tagPages,
        allTags: Array.from(tagMap.keys()).sort(),
        site: { title: config.siteTitle, description: config.siteDescription, baseUrl: config.baseUrl },
      };
      writeFileSync(tagFile, renderWithLayout("tag", layout, data));
    }
  }

  // Generate RSS
  const rssXml = generateRSS(pages, config);
  writeFileSync(join(config.output, "rss.xml"), rssXml);

  // Copy static assets from templates/assets if they exist
  const assetsDir = join(config.templates, "assets");
  if (existsSync(assetsDir)) {
    copyAssets(assetsDir, config.output);
  }
}

function copyAssets(src: string, dest: string): void {
  const entries = readdirSync(src, { withFileTypes: true });
  for (const entry of entries) {
    const srcPath = join(src, entry.name);
    const destPath = join(dest, entry.name);
    if (entry.isDirectory()) {
      mkdirSync(destPath, { recursive: true });
      copyAssets(srcPath, destPath);
    } else {
      mkdirSync(dirname(destPath), { recursive: true });
      copyFileSync(srcPath, destPath);
    }
  }
}

import { createServer, IncomingMessage, ServerResponse } from "node:http";
import { readFileSync, existsSync, statSync } from "node:fs";
import { join, extname } from "node:path";
import { WebSocketServer, WebSocket } from "ws";
import type { SiteConfig } from "./types.js";

const RELOAD_SCRIPT = `<script>(function(){var s=new WebSocket('ws://'+(location.host||'localhost:3000')+'/__livereload');s.onmessage=function(e){if(e.data==='reload')location.reload();};})();</script>`;

const MIME: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css",
  ".js": "application/javascript",
  ".json": "application/json",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
  ".xml": "application/xml",
};

export function createDevServer(config: SiteConfig, port: number): { server: ReturnType<typeof createServer>; reload: () => void } {
  const clients = new Set<WebSocket>();

  const server = createServer((req: IncomingMessage, res: ServerResponse) => {
    const url = new URL(req.url || "/", `http://localhost:${port}`);
    let filePath = join(config.output, url.pathname);

    if (filePath.endsWith("/") || !extname(filePath)) {
      filePath = join(filePath, "index.html");
    }

    if (!existsSync(filePath) || !statSync(filePath).isFile()) {
      filePath = join(config.output, "index.html");
    }

    if (!existsSync(filePath)) {
      res.writeHead(404);
      res.end("Not found");
      return;
    }

    const ext = extname(filePath);
    const mime = MIME[ext] || "application/octet-stream";

    try {
      let content = readFileSync(filePath);
      if (ext === ".html" || mime.startsWith("text/html")) {
        let html = content.toString("utf-8");
        if (!html.includes("__livereload")) {
          html = html.replace("</body>", RELOAD_SCRIPT + "</body>");
        }
        content = Buffer.from(html);
      }
      res.writeHead(200, { "Content-Type": mime });
      res.end(content);
    } catch {
      res.writeHead(500);
      res.end("Internal server error");
    }
  });

  const wss = new WebSocketServer({ noServer: true });

  server.on("upgrade", (req, socket, head) => {
    if (req.url === "/__livereload") {
      wss.handleUpgrade(req, socket, head, (ws) => {
        clients.add(ws);
        ws.on("close", () => clients.delete(ws));
      });
    } else {
      socket.destroy();
    }
  });

  function reload() {
    const msg = JSON.stringify("reload");
    for (const client of clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send("reload");
      }
    }
  }

  return { server, reload };
}

#!/usr/bin/env node
import { program } from "commander";
import { resolve } from "node:path";
import { watch } from "chokidar";
import type { SiteConfig } from "./types.js";
import { build } from "./generator.js";
import { createDevServer } from "./server.js";

program
  .name("ssg")
  .description("A static site generator")
  .version("1.0.0");

program
  .command("build")
  .description("Build the static site")
  .option("-s, --source <path>", "Source directory of markdown files", "content")
  .option("-t, --templates <path>", "Template directory with Handlebars files", "templates")
  .option("-o, --output <path>", "Output directory for generated site", "public")
  .option("-b, --base-url <url>", "Base URL for the site", "http://localhost:3000")
  .option("--site-title <title>", "Site title", "My Site")
  .option("--site-description <desc>", "Site description", "A static site")
  .option("--include-drafts", "Include draft posts", false)
  .action((opts) => {
    const config: SiteConfig = {
      source: resolve(opts.source),
      templates: resolve(opts.templates),
      output: resolve(opts.output),
      baseUrl: opts.baseUrl,
      includeDrafts: opts.includeDrafts,
      siteTitle: opts.siteTitle,
      siteDescription: opts.siteDescription,
    };
    console.log("Building site...");
    build(config);
    console.log(`Site built to ${config.output}`);
  });

program
  .command("serve")
  .description("Start a dev server with live reload")
  .option("-s, --source <path>", "Source directory of markdown files", "content")
  .option("-t, --templates <path>", "Template directory with Handlebars files", "templates")
  .option("-o, --output <path>", "Output directory for generated site", "public")
  .option("-b, --base-url <url>", "Base URL for the site", "http://localhost:3000")
  .option("-p, --port <number>", "Port for the dev server", "3000")
  .option("--site-title <title>", "Site title", "My Site")
  .option("--site-description <desc>", "Site description", "A static site")
  .option("--include-drafts", "Include draft posts", false)
  .action((opts) => {
    const config: SiteConfig = {
      source: resolve(opts.source),
      templates: resolve(opts.templates),
      output: resolve(opts.output),
      baseUrl: opts.baseUrl,
      includeDrafts: opts.includeDrafts,
      siteTitle: opts.siteTitle,
      siteDescription: opts.siteDescription,
    };
    const port = parseInt(opts.port, 10);

    console.log("Building site...");
    build(config);

    const { server, reload } = createDevServer(config, port);

    server.listen(port, () => {
      console.log(`Dev server running at http://localhost:${port}`);
    });

    const watchPaths = [config.source, config.templates];
    const watcher = watch(watchPaths, {
      ignoreInitial: true,
      awaitWriteFinish: { stabilityThreshold: 200, pollInterval: 100 },
    });

    watcher.on("all", (_event, _path) => {
      console.log("Changes detected, rebuilding...");
      try {
        build(config);
        reload();
        console.log("Rebuild complete.");
      } catch (err) {
        console.error("Build error:", err);
      }
    });
  });

program.parse();

